<?php $enrolledUsers = is_array($enrolledUsers ?? null) ? $enrolledUsers : []; ?>
<section class="page-header"><div><p class="dashboard-kicker mb-1">Reconocimiento Facial</p><h1 class="fw-bold mb-1">Reconocimientos Enrolados</h1><p class="text-muted mb-0">Usuarios de tu empresa con enrolamiento facial registrado.</p></div></section>
<section class="card content-panel"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Usuarios enrolados</h2><span class="badge text-bg-light border"><?= count($enrolledUsers) ?> usuario(s)</span></div>
<?php if (!$enrolledUsers): ?><div class="alert alert-info mb-0">No hay reconocimientos enrolados para esta empresa.</div><?php else: ?><table class="table table-hover align-middle app-table app-data-table"><thead><tr><th>Usuario</th><th>RUT</th><th>Correo</th><th>Estado</th><th>Fecha enrolamiento</th></tr></thead><tbody><?php foreach ($enrolledUsers as $person): ?><tr><td><?= e((string) ($person['name'] ?? 'Usuario')) ?></td><td><?= e((string) ($person['rut'] ?? '')) ?></td><td><?= e((string) ($person['email'] ?? '')) ?></td><td><span class="badge text-bg-<?= ($person['status'] ?? '') === 'active' ? 'success' : 'secondary' ?>"><?= e(($person['status'] ?? '') === 'active' ? 'Activo' : 'Revocado') ?></span></td><td><?= e((string) ($person['enrolled_at'] ?? 'Sin fecha')) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
</section>
